","import React, { useState, useEffect } from "react";

interface Props {
 navigate: (view: string, extras?: { type?: string; id?: string }) => void;
 userName?: string;
 studentSysId?: string;
}

function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 Accept: "application/json",
 "Content-Type": "application/json",
 };
 const token = (window as any).g_ck;
 if (token) headers["X-UserToken"] = token;
 return headers;
}

function getGreeting(): string {
 const hour = new Date().getHours();
 if (hour < 12) return "Good Morning";
 if (hour < 17) return "Good Afternoon";
 return "Good Evening";
}

function getStatusColor(state: string): { bg: string; text: string } {
 const s = state.toLowerCase();
 if (s === "open") return { bg: "#fff8e1", text: "#f57f17" };
 if (s === "in progress") return { bg: "#e3f2fd", text: "#1565c0" };
 if (s === "resolved" || s === "approved") return { bg: "#e8f5e9", text: "#2e7d32" };
 return { bg: "#f5f5f5", text: "#616161" };
}

export default function HomeScreen({ navigate, userName, studentSysId }: Props) {
 const [displayName, setDisplayName] = useState("Student");
 const [recentCases, setRecentCases] = useState<any[]>([]);
 const [activeBus, setActiveBus] = useState<any>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 // Use the userName prop if available, else fallback to NOW user
 if (userName) {
 setDisplayName(userName);
 } else {
 const nowUser = (window as any).NOW?.user_display_name;
 if (nowUser) setDisplayName(nowUser);
 }
 }, [userName]);

 useEffect(() => {
 const fetchData = async () => {
 try {
 // Build case query - filter by student if available
 let caseQuery = "ORDERBYDESCsys_created_on";
 if (studentSysId) {
 caseQuery = `u_student_id=${studentSysId}^${caseQuery}`;
 }

 const [casesRes, busRes] = await Promise.all([
 fetch(
 `/api/now/table/u_transportation_case?sysparm_limit=3&sysparm_query=${encodeURIComponent(caseQuery)}&sysparm_display_value=all`,
 { headers: getHeaders() }
 ),
 fetch(
 "/api/now/table/u_bus?sysparm_limit=1&sysparm_query=u_bus_status=active&sysparm_display_value=all",
 { headers: getHeaders() }
 ),
 ]);

 if (casesRes.ok) {
 const casesData = await casesRes.json();
 setRecentCases(casesData.result || []);
 }

 if (busRes.ok) {
 const busData = await busRes.json();
 const buses = busData.result || [];
 if (buses.length > 0) setActiveBus(buses[0]);
 }
 } catch (e) {
 // Silently handle - home screen degrades gracefully
 } finally {
 setLoading(false);
 }
 };

 fetchData();
 }, [studentSysId]);

 const greeting = getGreeting();

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 {/* Header gradient */}
 <div style={{
 background: "linear-gradient(135deg, #0066cc 0%, #004999 100%)",
 borderRadius: 16,
 padding: 20,
 marginBottom: 20,
 color: "#fff",
 }}>
 <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
 <span style={{ fontSize: 28 }}>👋</span>
 <div>
 <div style={{ fontSize: 14, opacity: 0.9 }}>{greeting},</div>
 <div style={{ fontSize: 20, fontWeight: 700 }}>{displayName}</div>
 </div>
 </div>
 </div>

 {/* Next Bus card */}
 <div
 onClick={() => navigate("mybus")}
 style={{
 background: "#fff",
 borderRadius: 14,
 padding: 16,
 marginBottom: 20,
 boxShadow: "0 2px 12px rgba(0,0,0,0.06)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#0066cc" strokeWidth="2">
 <path d="M4 16V6a4 4 0 014-4h8a4 4 0 014 4v10M4 16h16M4 16l-2 3h20l-2-3M8 20v1M16 20v1M8 10h8" />
 </svg>
 <span style={{ fontSize: 14, fontWeight: 600, color: "#333" }}>Your Next Bus</span>
 {activeBus && (
 <span style={{
 marginLeft: "auto",
 fontSize: 11,
 fontWeight: 600,
 padding: "3px 10px",
 borderRadius: 10,
 background: "#e8f5e9",
 color: "#2e7d32",
 }}>
 {dv(activeBus.u_bus_status) || "Active"}
 </span>
 )}
 </div>

 {loading ? (
 <div style={{ textAlign: "center", padding: "12px 0" }}>
 <div style={{ width: 20, height: 20, border: "2px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite", margin: "0 auto" }} />
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 ) : activeBus ? (
 <div>
 <div style={{ fontSize: 16, fontWeight: 700, color: "#1a1a1a", marginBottom: 4 }}>
 Bus {dv(activeBus.u_bus_number)}
 </div>
 <div style={{ fontSize: 13, color: "#666", marginBottom: 2 }}>
 Route: {dv(activeBus.u_route)}
 </div>
 {dv(activeBus.u_last_location_update) && (
 <div style={{ fontSize: 11, color: "#999" }}>
 Last update: {dv(activeBus.u_last_location_update)}
 </div>
 )}
 </div>
 ) : (
 <div style={{ fontSize: 13, color: "#999" }}>No active buses at the moment</div>
 )}
 </div>

 {/* Quick Actions */}
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a", marginBottom: 12 }}>Quick Actions</div>
 <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 24 }}>
 <div
 onClick={() => navigate("report")}
 style={{
 background: "#fff",
 borderRadius: 12,
 padding: 16,
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 gap: 8,
 boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#e53935" strokeWidth="2">
 <path d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
 </svg>
 <span style={{ fontSize: 12, fontWeight: 600, color: "#333" }}>Report Issue</span>
 </div>
 <div
 onClick={() => navigate("buspass")}
 style={{
 background: "#fff",
 borderRadius: 12,
 padding: 16,
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 gap: 8,
 boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0066cc" strokeWidth="2">
 <rect x="2" y="5" width="20" height="14" rx="2" />
 <path d="M2 10h20" />
 </svg>
 <span style={{ fontSize: 12, fontWeight: 600, color: "#333" }}>Bus Pass</span>
 </div>
 <div
 onClick={() => navigate("lostfound")}
 style={{
 background: "#fff",
 borderRadius: 12,
 padding: 16,
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 gap: 8,
 boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#ff9800" strokeWidth="2">
 <circle cx="11" cy="11" r="8" /><path d="M21 21l-4.35-4.35" />
 </svg>
 <span style={{ fontSize: 12, fontWeight: 600, color: "#333" }}>Lost & Found</span>
 </div>
 <div
 onClick={() => navigate("emergency")}
 style={{
 background: "#fff",
 borderRadius: 12,
 padding: 16,
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 gap: 8,
 boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#9c27b0" strokeWidth="2">
 <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 006 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5M9 18h6M10 22h4" />
 </svg>
 <span style={{ fontSize: 12, fontWeight: 600, color: "#333" }}>Emergency</span>
 </div>
 </div>

 {/* Recent Updates */}
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a", marginBottom: 12 }}>Recent Updates</div>

 {loading ? (
 <div style={{ textAlign: "center", padding: 20 }}>
 <div style={{ width: 24, height: 24, border: "3px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite", margin: "0 auto" }} />
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 ) : recentCases.length === 0 ? (
 <div style={{ textAlign: "center", padding: "20px 16px", color: "#888", fontSize: 13 }}>
 No recent activity. Report an issue to get started!
 </div>
 ) : (
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {recentCases.map((c) => {
 const state = dv(c.u_state);
 const colors = getStatusColor(state);
 return (
 <div
 key={getSysId(c)}
 onClick={() => navigate("request-detail", { id: getSysId(c) })}
 style={{
 display: "flex",
 alignItems: "center",
 gap: 12,
 padding: "12px 14px",
 background: "#fff",
 borderRadius: 10,
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 }}
 >
 <div style={{
 width: 8,
 height: 8,
 borderRadius: "50%",
 background: colors.text,
 flexShrink: 0,
 }} />
 <div style={{ flex: 1, minWidth: 0 }}>
 <div style={{ fontSize: 13, fontWeight: 600, color: "#1a1a1a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
 {dv(c.u_short_description) || dv(c.u_issue_type)}
 </div>
 <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>
 {dv(c.u_number)} · {dv(c.sys_created_on)}
 </div>
 </div>
 <span style={{
 fontSize: 10,
 fontWeight: 600,
 padding: "2px 8px",
 borderRadius: 8,
 background: colors.bg,
 color: colors.text,
 whiteSpace: "nowrap",
 }}>
 {state}
 </span>
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
}
