 margin-bottom: var(--now-static-space--md, 1rem);
 padding-bottom: var(--now-static-space--md, 1rem);
 border-bottom: 1px solid rgb(var(--now-container-card--border-color, 218, 220, 224));
}

.ms-admin-modal-field {
 display: flex;
