export default function RequestDetailScreen({ navigate, requestId }: Props) {
 const [caseData, setCaseData] = useState<any>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");

 useEffect(() => {
 if (!requestId) {
 setError("No request ID provided.");
 setLoading(false);
 return;
 }

 const fetchCase = async () => {
 try {
 const res = await fetch(
 `/api/now/table/u_transportation_case/${requestId}?sysparm_display_value=all`,
 { headers: getHeaders() }
 );
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const data = await res.json();
 setCaseData(data.result);
 } catch (e: any) {
 setError(e.message || "Failed to load request details.");
 } finally {
 setLoading(false);
 }
 };
 fetchCase();
 }, [requestId]);

 if (loading) {
 return (
 <div style={{ padding: 16, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh" }}>
 <div style={{ width: 40, height: 40, border: "4px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
 <p style={{ marginTop: 16, color: "#666", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>Loading details...</p>
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 );
 }

 if (error || !caseData) {
 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 <button
 onClick={() => navigate("requests")}
 style={{ background: "none", border: "none", padding: 4, cursor: "pointer", display: "flex", alignItems: "center", marginBottom: 16 }}
 >
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#333" strokeWidth="2">
 <path d="M19 12H5M12 19l-7-7 7-7" />
 </svg>
 <span style={{ marginLeft: 8, fontSize: 14, color: "#333" }}>Back</span>
 </button>
 <div style={{ background: "#fdecea", color: "#c62828", padding: 16, borderRadius: 8, fontSize: 14 }}>
 {error || "Request not found."}
 </div>
 </div>
 );
 }

 const caseNumber = dv(caseData.u_number);
 const issueType = dv(caseData.u_issue_type);
 const state = dv(caseData.u_state);
 const severity = dv(caseData.u_severity);
 const priority = dv(caseData.u_priority);
 const shortDesc = dv(caseData.u_short_description);
 const description = dv(caseData.u_description);
 const solutionResponse = dv(caseData.u_solution_response);
 const resolutionNotes = dv(caseData.u_resolution_notes);
 const currentBus = dv(caseData.u_current_bus);
 const currentRoute = dv(caseData.u_current_route);
 const currentStop = dv(caseData.u_current_bus_stop);
 const requestedRoute = dv(caseData.u_requested_route);
