 </div>
 </div>
 );
 }

 return (
 <div style={screenStyle}>
 {/* Header */}
 <div style={{
 backgroundColor: "#ffffff",
 padding: "20px 16px",
 borderBottom: "1px solid #e8ecf0",
 display: "flex",
 alignItems: "center",
 justifyContent: "space-between",
 }}>
 <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
 <div style={{
 width: "44px",
 height: "44px",
 borderRadius: "12px",
 background: "linear-gradient(135deg, #5b2d8e 0%, #7c3aed 100%)",
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 fontSize: "20px",
 }}>📊</div>
 <div>
 <div style={{ fontSize: "12px", color: "#6c757d", fontWeight: 500, letterSpacing: "0.5px", textTransform: "uppercase" }}>Transportation</div>
 <div style={{ fontSize: "20px", fontWeight: 700, color: "#1a1a2e" }}>Admin Console</div>
 </div>
 </div>
 <button
 onClick={() => { setLoading(true); fetchCases(); }}
 style={{
 width: "38px",
 height: "38px",
 borderRadius: "10px",
 border: "1px solid #e8ecf0",
 backgroundColor: "#f8f9fa",
 display: "flex",
