 justifyContent: "center",
 cursor: "pointer",
 fontSize: "18px",
 }}
 >🔄</button>
 </div>

 {/* Stats Row */}
 <div style={{ display: "flex", gap: "10px", padding: "16px" }}>
 <div style={{
 flex: 1,
