 );
}
","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";
import HomeScreen from "./components/HomeScreen";
import ReportIssueScreen from "./components/ReportIssueScreen";
import IssueFormScreen from "./components/IssueFormScreen";
import MyBusScreen from "./components/MyBusScreen";
import BusPassScreen from "./components/BusPassScreen";
import MyRequestsScreen from "./components/MyRequestsScreen";
import RequestDetailScreen from "./components/RequestDetailScreen";
import LostFoundScreen from "./components/LostFoundScreen";
import EmergencyScreen from "./components/EmergencyScreen";
import ProfileScreen from "./components/ProfileScreen";
import BottomNav from "./components/BottomNav";
import ChatWidget from "./components/ChatWidget";
import RoleSwitcher from "./components/RoleSwitcher";
import DriverHome from "./components/DriverHome";
import DriverNav from "./components/DriverNav";
import AdminHome from "./components/AdminHome";
import AdminNav from "./components/AdminNav";

type Role = "student" | "driver" | "admin";

interface ViewState {
 view: string;
 type: string | null;
 id: string | null;
}

function getRoleFromUrl(): Role {
 const params = new URLSearchParams(window.location.search);
 const role = params.get("role");
 if (role === "driver" || role === "admin") return role;
 return "student";
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 type: params.get("type") || null,
 id: params.get("id") || null,
 };
}

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 Accept: "application/json",
 "Content-Type": "application/json",
 };
 const token = (window as any).g_ck;
 if (token) headers["X-UserToken"] = token;
 return headers;
}

function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

export default function App() {
 const [role, setRole] = useState<Role>(getRoleFromUrl);
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);
 const [studentProfile, setStudentProfile] = useState<any>(null);
 const [driverProfile, setDriverProfile] = useState<any>(null);
 const [userName, setUserName] = useState<string>("");

 useEffect(() => {
 const onPopState = () => {
 setCurrentView(getViewFromUrl());
 setRole(getRoleFromUrl());
 };
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 // Fetch student and driver profiles on mount
 useEffect(() => {
 const fetchProfiles = async () => {
 try {
 // Fetch first active student
 const studentRes = await fetch(
 "/api/now/table/u_student?sysparm_limit=1&sysparm_query=u_is_active=true&sysparm_display_value=all",
 { headers: getHeaders() }
 );
 if (studentRes.ok) {
 const studentData = await studentRes.json();
 const students = studentData.result || [];
 if (students.length > 0) {
 const student = students[0];
 setStudentProfile(student);

 // Get display name from the u_user reference field (display_value=all gives us the display name)
 const userDisplayName = dv(student.u_user);
 if (userDisplayName) {
 setUserName(userDisplayName);
 } else {
 // Fallback: fetch from sys_user if we have the reference value
 const userRef = student.u_user?.value;
 if (userRef) {
 try {
 const userRes = await fetch(
 `/api/now/table/sys_user/${userRef}?sysparm_fields=name,email,user_name`,
 { headers: getHeaders() }
 );
 if (userRes.ok) {
 const userData = await userRes.json();
 const nameVal = userData.result?.name || userData.result?.user_name || "";
 if (nameVal) setUserName(nameVal);
 }
 } catch (_) {
 // Silently fail
 }
 }
 }
 }
 }
 } catch (_) {
 // Silently fail - app degrades gracefully
 }

 try {
 // Fetch first available driver
 const driverRes = await fetch(
 "/api/now/table/u_driver?sysparm_limit=1&sysparm_query=u_is_available=true&sysparm_display_value=all",
 { headers: getHeaders() }
 );
 if (driverRes.ok) {
 const driverData = await driverRes.json();
 const drivers = driverData.result || [];
 if (drivers.length > 0) {
 setDriverProfile(drivers[0]);
 }
 }
 } catch (_) {
 // Silently fail
 }
 };

 fetchProfiles();
 }, []);

 const navigate = useCallback(
 (viewName: string, extras?: { type?: string; id?: string }) => {
 const params = new URLSearchParams(window.location.search);
 params.set("view", viewName);
 if (extras?.type) {
 params.set("type", extras.type);
 } else {
 params.delete("type");
 }
 if (extras?.id) {
 params.set("id", extras.id);
 } else {
 params.delete("id");
 }
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState({}, "", path);
 setCurrentView({
 view: viewName,
 type: extras?.type || null,
 id: extras?.id || null,
 });
 },
 []
 );

 const { view, type, id } = currentView;
 const studentSysId = getSysId(studentProfile);

 // Student screens
 const renderStudentScreen = () => {
 switch (view) {
 case "home":
 return <HomeScreen navigate={navigate} userName={userName} studentSysId={studentSysId} />;
 case "report":
 return <ReportIssueScreen navigate={navigate} />;
 case "issue-form":
 return <IssueFormScreen navigate={navigate} issueType={type} studentSysId={studentSysId} />;
 case "mybus":
 return <MyBusScreen navigate={navigate} />;
 case "buspass":
 return <BusPassScreen navigate={navigate} />;
 case "requests":
 return <MyRequestsScreen navigate={navigate} studentSysId={studentSysId} />;
 case "request-detail":
 return <RequestDetailScreen navigate={navigate} requestId={id} />;
 case "lostfound":
 return <LostFoundScreen navigate={navigate} />;
 case "emergency":
 return <EmergencyScreen navigate={navigate} />;
 case "profile":
 return <ProfileScreen navigate={navigate} studentProfile={studentProfile} userName={userName} />;
 default:
 return <HomeScreen navigate={navigate} userName={userName} studentSysId={studentSysId} />;
 }
 };

 // Driver screens
 const renderDriverScreen = () => {
 return <DriverHome driverProfile={driverProfile} />;
 };

 // Admin screens
 const renderAdminScreen = () => {
 return <AdminHome />;
 };

 return (
 <div className="ms-app">
 <RoleSwitcher role={role} setRole={setRole} />
 <div className="ms-content">
 {role === "student" && renderStudentScreen()}
 {role === "driver" && renderDriverScreen()}
 {role === "admin" && renderAdminScreen()}
 </div>
 {role === "student" && <BottomNav currentView={view} navigate={navigate} />}
 {role === "driver" && <DriverNav currentView={view} navigate={navigate} />}
 {role === "admin" && <AdminNav currentView={view} navigate={navigate} />}
 {role === "student" && <ChatWidget />}
 </div>
 );
}
